// WidgetKing AI proxy — Supabase Edge Function.
// GENERATED by tools/gen_ai_proxy.mjs from index.src.ts + policy.js into
// index.ts (one file, so it can be pasted into the dashboard editor).
// Edit the .src.ts and policy.js, then: node tools/gen_ai_proxy.mjs
//
// The Anthropic key lives here (secret ANTHROPIC_API_KEY), never in the app.
// Every call: verify the Supabase session → load Pro status + this month's
// usage → decide (policy.js) → forward to Anthropic → record the cost.
//   POST  : an Anthropic Messages request body; returns the Anthropic JSON
//           plus x-wk-* headers (model used, tier, builds left, downshift)
//   GET   : { quota } for the signed-in user, no model call
// Secrets: ANTHROPIC_API_KEY (required); RESEND_API_KEY + ALERT_EMAIL +
//          ALERT_FROM (optional: emails Andrew when the daily breaker trips)
import { createClient } from "npm:@supabase/supabase-js@2";

//__POLICY__

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-wk-device, x-wk-build",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Expose-Headers": "x-wk-model, x-wk-tier, x-wk-high-left, x-wk-high-total, x-wk-free-left, x-wk-free-total, x-wk-reason"
};
const json = (status: number, body: unknown, extra: Record<string, string> = {}) =>
  new Response(JSON.stringify(body), { status, headers: { ...CORS, ...extra, "content-type": "application/json" } });

const MESSAGES: Record<string, string> = {
  paused: "The AI designer is taking a short break — try again in a little while",
  free: "You've used your " + LIMITS.freeBuilds + " free AI builds this month — Pro unlocks unlimited builds",
  monthly: "You've reached this month's fair-use limit for AI builds — it resets on the 1st",
  daily: "That's a lot of building for one day — the AI designer is back tomorrow",
  build: "This build already had its passes — start a new one"
};

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });
  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY") ?? "";
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  const anthropicKey = Deno.env.get("ANTHROPIC_API_KEY") ?? "";
  const auth = req.headers.get("Authorization") ?? "";
  if (!auth.startsWith("Bearer ")) return json(401, { error: { message: "Sign in to use the AI designer" } });

  // Who is calling? The session token is verified by Supabase Auth itself.
  const asUser = createClient(supabaseUrl, anonKey, { global: { headers: { Authorization: auth } } });
  const { data: userData, error: userErr } = await asUser.auth.getUser();
  if (userErr || !userData?.user) return json(401, { error: { message: "Your sign-in expired — sign in again to keep building" } });
  const userId = userData.user.id;
  const deviceId = (req.headers.get("x-wk-device") ?? "").slice(0, 80) || "unknown";
  const buildId = (req.headers.get("x-wk-build") ?? "").slice(0, 80) || crypto.randomUUID();

  const admin = createClient(supabaseUrl, serviceKey);
  const { data: summary, error: sumErr } = await admin.rpc("ai_usage_summary", { p_user: userId, p_device: deviceId, p_build: buildId });
  if (sumErr) return json(500, { error: { message: "Usage lookup failed: " + sumErr.message } });
  const s = (summary ?? {}) as Record<string, number | boolean>;
  const usage = {
    userMonthCost: Number(s.user_month_cost ?? 0),
    userMonthHighCost: Number(s.user_month_high_cost ?? 0),
    userMonthBuilds: Number(s.user_month_builds ?? 0),
    userTodayBuilds: Number(s.user_today_builds ?? 0),
    deviceMonthBuilds: Number(s.device_month_builds ?? 0),
    buildCalls: Number(s.build_calls ?? 0),
    globalTodayCost: Number(s.global_today_cost ?? 0)
  };
  const pro = !!s.pro;

  if (req.method === "GET") return json(200, { quota: quotaFor(pro, usage, LIMITS) });
  if (req.method !== "POST") return json(405, { error: { message: "Method not allowed" } });
  if (!anthropicKey) return json(503, { error: { message: "The AI designer isn't configured yet" } });

  let body: Record<string, unknown>;
  try { body = await req.json(); } catch { return json(400, { error: { message: "Bad request" } }); }
  const d = decide({ pro, requestedModel: String(body.model ?? ""), usage });
  const quotaHeaders = headersFor(d.model, d.quota, d.reason);
  if (!d.allow) {
    if (d.reason === "paused") await alertIfNeeded(admin, usage.globalTodayCost);
    const status = d.reason === "paused" ? 503 : d.reason === "free" ? 402 : 429;
    return json(status, { error: { message: MESSAGES[d.reason] ?? "Not allowed", code: d.reason } }, quotaHeaders);
  }
  const forward = sanitizeBody(body, d.model, LIMITS);
  if (!forward) return json(400, { error: { message: "Bad request" } });

  const upstream = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "content-type": "application/json", "x-api-key": anthropicKey, "anthropic-version": "2023-06-01" },
    body: JSON.stringify(forward)
  });
  const text = await upstream.text();
  if (!upstream.ok) {
    let message = "AI designer error " + upstream.status;
    try { const j = JSON.parse(text); if (j.error?.message) message = j.error.message; } catch { /* keep */ }
    return json(upstream.status === 429 || upstream.status >= 500 ? 503 : 400, { error: { message } }, quotaHeaders);
  }
  let cost = 0;
  try { const j = JSON.parse(text); cost = costOf(d.model, j.usage); } catch { /* unparsable: still record the call */ }
  await admin.from("ai_usage").insert({ user_id: userId, device_id: deviceId, build_id: buildId, model: d.model, cost_usd: cost });
  return new Response(text, { status: 200, headers: { ...CORS, ...quotaHeaders, "content-type": "application/json" } });
});

function headersFor(model: string, q: Record<string, unknown>, reason: string): Record<string, string> {
  const h: Record<string, string> = { "x-wk-model": model, "x-wk-tier": String(q.tier), "x-wk-reason": reason };
  if (q.tier === "pro") { h["x-wk-high-left"] = String(q.highLeft); h["x-wk-high-total"] = String(q.highTotal); }
  else { h["x-wk-free-left"] = String(q.freeLeft); h["x-wk-free-total"] = String(q.freeTotal); }
  return h;
}

// One email per day when the global breaker trips; silent when Resend isn't set up.
async function alertIfNeeded(admin: ReturnType<typeof createClient>, spent: number) {
  const day = new Date().toISOString().slice(0, 10);
  const { error } = await admin.from("ai_alerts").insert({ day });
  if (error) return; // already alerted today (primary key) or table missing
  const key = Deno.env.get("RESEND_API_KEY"), to = Deno.env.get("ALERT_EMAIL"), from = Deno.env.get("ALERT_FROM");
  if (!key || !to || !from) return;
  await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: { "content-type": "application/json", Authorization: "Bearer " + key },
    body: JSON.stringify({ from, to: [to], subject: "WidgetKing AI paused — daily spend breaker tripped",
      text: "AI spend today reached $" + spent.toFixed(2) + " (limit $" + LIMITS.globalDailyCost.toFixed(2) + "). The AI designer is paused for everyone until midnight UTC. If this isn't real traffic, check the Edge Function logs for a loop." })
  }).catch(() => {});
}
